import{_ as t,c as a,o,aj as n}from"./chunks/framework.BlveriQe.js";const p=JSON.parse('{"title":"Interface: FunctionsAPI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/FunctionsAPI.md","filePath":"reference/js-bao-wss-client/api/interfaces/FunctionsAPI.md"}'),r={name:"reference/js-bao-wss-client/api/interfaces/FunctionsAPI.md"};function i(s,e,c,d,h,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / FunctionsAPI</p><h1 id="interface-functionsapi" tabindex="-1">Interface: FunctionsAPI <a class="header-anchor" href="#interface-functionsapi" aria-label="Permalink to “Interface: FunctionsAPI”">​</a></h1><p>Server functions, available as <code>client.functions</code>.</p><p>A function is TypeScript an app&#39;s team authored in its config tree and pushed with <code>primitive config push</code>. Invoking one runs it on the platform under the calling user&#39;s own authority and returns its result.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="getstatus" tabindex="-1">getStatus() <a class="header-anchor" href="#getstatus" aria-label="Permalink to “getStatus()”">​</a></h3><blockquote><p><strong>getStatus</strong>&lt;<code>TOutput</code>&gt;(<code>runId</code>): <code>Promise</code>&lt;<a href="./FunctionRunStatus.html"><code>FunctionRunStatus</code></a>&lt;<code>TOutput</code>&gt;&gt;</p></blockquote><p>The current status of a function run, by run id.</p><p>Which route the client polls is an implementation choice and nothing more. The ANSWER is function-native: one structured <code>error</code> with the platform&#39;s <code>code</code> on it, a <code>run</code> block carrying only fields a function row has, and none of the workflow DSL&#39;s vocabulary, which could never be set for a function.</p><p>A run id that is not this app&#39;s, or does not exist, is <code>NOT_FOUND &quot;Function run &lt;id&gt; not found&quot;</code>. Every other refusal — a 403 from the access gate, a 5xx — propagates as it arrived.</p><h4 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="toutput" tabindex="-1">TOutput <a class="header-anchor" href="#toutput" aria-label="Permalink to “TOutput”">​</a></h5><p><code>TOutput</code> = <code>unknown</code></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="runid" tabindex="-1">runId <a class="header-anchor" href="#runid" aria-label="Permalink to “runId”">​</a></h5><p><code>string</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./FunctionRunStatus.html"><code>FunctionRunStatus</code></a>&lt;<code>TOutput</code>&gt;&gt;</p><hr><h3 id="invoke" tabindex="-1">invoke() <a class="header-anchor" href="#invoke" aria-label="Permalink to “invoke()”">​</a></h3><blockquote><p><strong>invoke</strong>&lt;<code>TOutput</code>, <code>TInput</code>&gt;(<code>functionKey</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./FunctionInvokeResult.html"><code>FunctionInvokeResult</code></a>&lt;<code>TOutput</code>&gt;&gt;</p></blockquote><p>Invoke a server function on the REQUEST runtime and wait for its result.</p><p>The caller picks the runtime, and the ROUTE is how it is said: this method posts to <code>functions/{key}</code>, which runs the function inside the request. Every pushed function takes this verb and <code>start</code> alike — the config says nothing about how a function runs — so there is no configuration to change and no mismatch to refuse. A function that must NOT run under one of the two tests for it in its own code with <code>assertRuntime</code>, and the platform settles that as <code>status: &quot;failed&quot;</code> with <code>errorCode: &quot;FUNCTION_RUNTIME_REFUSED&quot;</code>.</p><p><code>input</code> is named for what it is on this side of the wire; it travels as the envelope&#39;s <code>rootInput</code>, which is the field name the workflow surfaces already use.</p><h4 id="type-parameters-1" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-1" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="toutput-1" tabindex="-1">TOutput <a class="header-anchor" href="#toutput-1" aria-label="Permalink to “TOutput”">​</a></h5><p><code>TOutput</code> = <code>unknown</code></p><h5 id="tinput" tabindex="-1">TInput <a class="header-anchor" href="#tinput" aria-label="Permalink to “TInput”">​</a></h5><p><code>TInput</code> = <code>unknown</code></p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="functionkey" tabindex="-1">functionKey <a class="header-anchor" href="#functionkey" aria-label="Permalink to “functionKey”">​</a></h5><p><code>string</code></p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./FunctionInvokeOptions.html"><code>FunctionInvokeOptions</code></a>&lt;<code>TInput</code>&gt; = <code>{}</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./FunctionInvokeResult.html"><code>FunctionInvokeResult</code></a>&lt;<code>TOutput</code>&gt;&gt;</p><hr><h3 id="start" tabindex="-1">start() <a class="header-anchor" href="#start" aria-label="Permalink to “start()”">​</a></h3><blockquote><p><strong>start</strong>&lt;<code>TInput</code>&gt;(<code>functionKey</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./FunctionStartResult.html"><code>FunctionStartResult</code></a>&gt;</p></blockquote><p>Start a server function on the TASK runtime and get its run id back.</p><p>The mirror of <code>invoke</code>, and the route says which: this method posts to <code>functions/{key}/start</code>. Every pushed function takes both verbs.</p><p>COMPATIBILITY, recorded: a client from this change against a server that predates it is answered <code>FUNCTION_ROUTE_FUNCTION_ONLY</code> on this route, which was function-principal-only before. The clients and the server ship together on alpha, so the window does not exist in practice.</p><p>The run is polled on exactly the routes a DSL workflow run is, which is why the methods below are aliases rather than a parallel protocol.</p><p><code>runKey</code> makes the start idempotent per <code>(caller, contextDocId, runKey)</code>: a repeat answers the run that already exists with <code>existing: true</code>, never a second run. There is no <code>forceRerun</code> on this route.</p><h4 id="type-parameters-2" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-2" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="tinput-1" tabindex="-1">TInput <a class="header-anchor" href="#tinput-1" aria-label="Permalink to “TInput”">​</a></h5><p><code>TInput</code> = <code>unknown</code></p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="functionkey-1" tabindex="-1">functionKey <a class="header-anchor" href="#functionkey-1" aria-label="Permalink to “functionKey”">​</a></h5><p><code>string</code></p><h5 id="options-1" tabindex="-1">options? <a class="header-anchor" href="#options-1" aria-label="Permalink to “options?”">​</a></h5><p><a href="./FunctionStartOptions.html"><code>FunctionStartOptions</code></a>&lt;<code>TInput</code>&gt; = <code>{}</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./FunctionStartResult.html"><code>FunctionStartResult</code></a>&gt;</p><hr><h3 id="terminate" tabindex="-1">terminate() <a class="header-anchor" href="#terminate" aria-label="Permalink to “terminate()”">​</a></h3><blockquote><p><strong>terminate</strong>&lt;<code>TOutput</code>&gt;(<code>ref</code>): <code>Promise</code>&lt;<a href="./FunctionRunStatus.html"><code>FunctionRunStatus</code></a>&lt;<code>TOutput</code>&gt;&gt;</p></blockquote><p>Terminate a running function run.</p><p>Posts the instance route itself rather than delegating: the workflow method mints <code>workflowKey is required for workflows.terminate</code> for an empty key and rewords nothing, so a function caller met the workflow vocabulary on every refusal.</p><p>A 404 from this route means THREE different things — no row, no instance id, and any exception out of the engine&#39;s own <code>terminate()</code> — and the body is how they are told apart (D3565-013). The first two are a function-worded <code>NOT_FOUND</code>; the third is an <code>UNAVAILABLE</code> carrying the engine&#39;s diagnostic verbatim, because a live run the engine could not stop is not a run that does not exist, and discarding what the engine said would leave a caller with nothing to act on.</p><h4 id="type-parameters-3" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-3" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="toutput-2" tabindex="-1">TOutput <a class="header-anchor" href="#toutput-2" aria-label="Permalink to “TOutput”">​</a></h5><p><code>TOutput</code> = <code>unknown</code></p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="ref" tabindex="-1">ref <a class="header-anchor" href="#ref" aria-label="Permalink to “ref”">​</a></h5><p><a href="./FunctionRunRef.html"><code>FunctionRunRef</code></a></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./FunctionRunStatus.html"><code>FunctionRunStatus</code></a>&lt;<code>TOutput</code>&gt;&gt;</p><hr><h3 id="waitfor" tabindex="-1">waitFor() <a class="header-anchor" href="#waitfor" aria-label="Permalink to “waitFor()”">​</a></h3><blockquote><p><strong>waitFor</strong>&lt;<code>TOutput</code>&gt;(<code>runId</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./../type-aliases/FunctionRunSettled.html"><code>FunctionRunSettled</code></a>&lt;<code>TOutput</code>&gt;&gt;</p></blockquote><p>Wait for a function run to reach a terminal state.</p><p>POLLS, where <code>workflows.waitFor</code> waits on a <code>workflowStatus</code> frame. That is not a stylistic difference: a function run broadcasts nothing over the WebSocket (D-3 — the contract for criterion 2 is poll-based), so a delegate to the workflow method would reconcile once, see <code>running</code>, and then wait out its whole <code>timeoutMs</code> with nothing left to wake it. Every other method on this class IS an alias; this one cannot be.</p><p>The interval starts short and backs off, so a function that finishes in a second is not waited out and one that sleeps for an hour is not polled thousands of times.</p><p>SETTLES on exactly <code>completed</code>, <code>failed</code> and <code>terminated</code>, which is what <a href="./../type-aliases/FunctionRunSettled.html">FunctionRunSettled</a> says its <code>status</code> is. A read reporting <code>missing</code> is a not-found — that run&#39;s execution can no longer be resolved and waiting for it to become terminal is waiting for nothing. A read reporting one of the DSL-only states (reachable only by handing this method a DSL run id, which is not refused) names the status in an <code>INVALID_ARGUMENT</code> rather than lying in the discriminator or spinning to the deadline.</p><p>A failed run RESOLVES with <code>status: &quot;failed&quot;</code> and its <code>error</code>; it does not throw. A transient error between polls is retried; a 404 is not.</p><h4 id="type-parameters-4" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-4" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="toutput-3" tabindex="-1">TOutput <a class="header-anchor" href="#toutput-3" aria-label="Permalink to “TOutput”">​</a></h5><p><code>TOutput</code> = <code>unknown</code></p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="runid-1" tabindex="-1">runId <a class="header-anchor" href="#runid-1" aria-label="Permalink to “runId”">​</a></h5><p><code>string</code></p><h5 id="options-2" tabindex="-1">options? <a class="header-anchor" href="#options-2" aria-label="Permalink to “options?”">​</a></h5><p><a href="./FunctionWaitOptions.html"><code>FunctionWaitOptions</code></a></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./../type-aliases/FunctionRunSettled.html"><code>FunctionRunSettled</code></a>&lt;<code>TOutput</code>&gt;&gt;</p>',88)])])}const f=t(r,[["render",i]]);export{p as __pageData,f as default};
